INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l25',4,5,25,'Non-auditory Effects of Noise','噪声的非听觉效应','neither … nor …(连接并列成分,动词就近一致)、过去分词作后置定语(an allegation often made)、whether 引导‘是否’的从句(discover whether …)、that 引导的表语从句(The snag is that …)、less … than / 比较级 + than(NCE4 无 KS 页,考点由课文结构自取;IP:源为 D.E. 布罗德本特《Science Survey》‘噪声的非听觉效应’一文,内容为‘噪声是否致精神病需大样本研究、轶事无凭’的科普论证事实,已用 100% 原创行文复述,无逐句改写;净化:打字员轶事改中性、删去‘孤儿院即健康危害’的污名措辞;题材=科学论证·无害;美语化 neighbor/analyze;第四册第25课·U5开工)','人们常争论噪声的作用,而这些作用并非全是听觉方面的——也就是说,并不都关乎听力本身。一种常被提出的指控是:噪声会引发精神疾病。某杂志曾登过一张令人揪心的照片:一个神情痛苦的女子,配着一行说明——‘又一个被折磨得心力交瘁的受害者’。翻到正文,读者才知道那女子是个打字员,她觉得办公室机器的咔嗒声越来越让人心烦,最后只好去看心理门诊。可这类轶事的毛病显而易见:我们怎么知道,真正的原因是噪声,而不是别的什么?一则故事再触目惊心,作为证据也是不充分的;一个审慎的读者,会对从中得出的任何确定结论持怀疑、不予采信。这个问题真正需要的,是对大量生活在噪声环境中的人做一番研究,看看他们是否比别人更常生病。若干年前,某国海军考察了大批在航空母舰上工作的人——他们与一个又一个喷气机中队共用甲板,那想必是地球上最吵的工作场所之一。然而,无论是精神科访谈还是客观测试,都无法显示噪声对这些水兵的心理有任何影响。如果噪声真会损害心理健康,那影响也必定小到现有的诊断手段都查不出来。这并不能证明影响不存在;但它确实提示:‘还世界一份安静’的呼吁,应当建立在诚实的证据上,而不是靠吓人的图片。降噪本是一桩好事,若被薄弱的论证拖累而失信,实在可惜。噪声很可能不如现代生活中许多别的压力那么危险;明智的做法,是在下结论之前,先把它的作用仔细量一量。','{"q":"Listen and answer — What conclusion does the author draw about noise and mental health?","options":["If noise affects mental health at all, the effect is too small for present methods to detect","Noise clearly causes madness","Noise has no effect on hearing","Noise is the greatest health hazard of our time"],"answer_index":0}'::jsonb,'{"title":"neither … nor / 过去分词作后置定语 / whether 从句 / 表语从句 / less … than","intro":"①neither A nor B,动词与靠近的 B 一致(就近原则):Neither the doctors nor the machine was able to …。②过去分词置于名词后作定语,表被动/完成:an allegation often made。③whether 引导‘是否’的从句:discover whether they are ill。④that 引导的从句放在 be 后作表语:The snag is that it proves nothing。⑤less … than / 比较级 + than。","table":{"headers":["用法","结构","例子"],"rows":[["neither … nor","Neither A nor B + 就近动词","Neither interviews nor tests were able to …"],["过去分词作定语","名词 + 过去分词","an allegation often made"],["whether 从句","discover whether …","discover whether they are ill"],["表语从句","be + that 从句","The snag is that it proves nothing"],["less … than","less + 形容词 + than","less dangerous than other strains"]]},"specialRules":[{"rule":"neither A nor B 作句子开头时,动词与更靠近的 B 保持一致(就近原则)。","mark":"就近一致"},{"rule":"非限定/后置的过去分词表被动或已完成(made / known / conducted);现在分词(working)表主动进行,别混。","mark":"made ≠ making"},{"rule":"美式拼写:neighbor(邻居,英式 neighbour)、analyze(分析,英式 analyse)。本课已按美语写。","mark":"neighbor / analyze"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l25',1,NULL,'People often argue about the effects of noise, and not all of those effects are auditory — that is, not all of them concern hearing itself. One allegation frequently made is that noise produces mental illness.','人们常争论噪声的作用,而这些作用并非全是听觉方面的——也就是说,并不都关乎听力本身。一种常被提出的指控是:噪声会引发精神疾病。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l25',2,NULL,'A magazine once ran a dramatic picture of a distressed woman under the caption, ''Another victim, worn down to a nervous state.'' Turning to the text, the reader learned that the woman was a typist who found the clatter of office machines more and more upsetting, until at last she sought help at a psychiatric clinic.','某杂志曾登过一张令人揪心的照片:一个神情痛苦的女子,配着一行说明——‘又一个被折磨得心力交瘁的受害者’。翻到正文,读者才知道那女子是个打字员,她觉得办公室机器的咔嗒声越来越让人心烦,最后只好去看心理门诊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l25',3,NULL,'The snag in this kind of anecdote is that we cannot be sure the noise, rather than something else, was the real cause. A single story, however striking, is inadequate as proof, and a careful reader will discredit any firm conclusion drawn from it.','可这类轶事的毛病显而易见:我们怎么知道,真正的原因是噪声,而不是别的什么?一则故事再触目惊心,作为证据也是不充分的;一个审慎的读者,会对从中得出的任何确定结论持怀疑、不予采信。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l25',4,NULL,'What the question really needs is a study of large numbers of people living under noisy conditions, to discover whether they fall ill more often than others do. Some years ago a navy examined a great many men who worked on aircraft carriers, sharing the deck with squadron after squadron of jet aircraft — surely one of the noisiest workplaces on earth.','这个问题真正需要的,是对大量生活在噪声环境中的人做一番研究,看看他们是否比别人更常生病。若干年前,某国海军考察了大批在航空母舰上工作的人——他们与一个又一个喷气机中队共用甲板,那想必是地球上最吵的工作场所之一。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l25',5,NULL,'Yet neither psychiatric interviews nor objective tests could show any mental effect of the noise upon these sailors. If noise harms mental health at all, the effect must be so small that present methods of diagnosis cannot find it. Noise abatement is a good cause, and it is a pity to see it discredited by weak arguments. Noise may well be less dangerous than many other strains of modern life.','然而,无论是精神科访谈还是客观测试,都无法显示噪声对这些水兵的心理有任何影响。如果噪声真会损害心理健康,那影响也必定小到现有的诊断手段都查不出来。降噪本是一桩好事,若被薄弱的论证拖累而失信,实在可惜。噪声很可能不如现代生活中许多别的压力那么危险。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
