INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l28','liter','litre','升;美语 liter,英式 litre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l28','put up with','',NULL,'/pʊt ʌp wɪð/','You must put up with the bitter taste.','你得忍受这苦味。','I can''t put up with the noise any longer.','我再也受不了这噪音了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l28','carry home','',NULL,'/ˈkæri hoʊm/','Patients like to carry home a bottle of medicine.','病人喜欢带一瓶药回家。','She carried home a bag of books.','她把一袋书带回了家。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l28','ask for','',NULL,'/æsk fɔːr/','Patients ask for pills, not advice.','病人要的是药片,不是劝告。','He asked for more time to finish.','他要求多给点时间完成。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l28','only too ready to','',NULL,'/ˈoʊnli tuː ˈredi tuː/','The doctor is only too ready to oblige.','医生巴不得顺水推舟。','I''m only too ready to help.','我非常乐意帮忙。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp1','choice','{"stem":"\"___ our faith in old beliefs has weakened, our trust in medicine has not.\"(‘尽管…’,让步连词,填句首那个词)","options":["Unless","Because","Since","Although"],"answer_index":3,"stem_cn":"尽管我们对旧信仰的信心已减弱,对药物的信任却未减。","explanation_cn":"‘尽管…’的让步连词是 Although。✓ Although our faith has weakened, our trust has not. ✗ Because(因为)/ Unless(除非)/ Since(既然):‘尽管’用 Although。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp1','choice','{"stem":"\"___ the doctor knows the pills may not help, he still prescribes them.\"(‘虽然’,让步连词)","options":["Because","Although","So","If"],"answer_index":1,"stem_cn":"虽然医生知道这些药丸也许没用,他还是开了。","explanation_cn":"‘虽然’的让步连词是 Although。✓ Although the doctor knows the pills may not help … ✗ Because / If / So:‘虽然’用 Although。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp1','choice','{"stem":"\"The patient felt cured, ___ the medicine was harmless water.\"(‘虽然/尽管’,填让步连词)","options":["although","unless","so","because"],"answer_index":0,"stem_cn":"病人觉得自己好了,尽管那药不过是无害的清水。","explanation_cn":"‘虽然/尽管’的让步连词是 although。✓ felt cured, although the medicine was harmless water. ✗ because / unless / so:让步用 although。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp2','choice','{"stem":"\"Patients feel neglected ___ they carry home a bottle of medicine.\"(‘除非’,条件连词)","options":["although","unless","because","since"],"answer_index":1,"stem_cn":"病人若不带一瓶药回家,就觉得被冷落了。","explanation_cn":"‘除非…’的条件连词是 unless。✓ feel neglected unless they carry home a bottle. ✗ because / although / since:‘除非’用 unless。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp2','choice','{"stem":"\"___ the doctor gives them something, they think nothing was done.\"(‘除非’,句首条件连词)","options":["Because","So","Unless","Although"],"answer_index":2,"stem_cn":"除非医生给点什么,他们就觉得什么也没做。","explanation_cn":"‘除非…’的条件连词是 Unless。✓ Unless the doctor gives them something … ✗ Because / Although / So:‘除非’用 Unless。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp2','choice','{"stem":"\"The illness will not improve ___ the patient changes his habits.\"(‘除非’,条件连词)","options":["while","unless","although","because"],"answer_index":1,"stem_cn":"除非病人改变习惯,否则病情不会好转。","explanation_cn":"‘除非…’的条件连词是 unless。✓ will not improve unless the patient changes his habits. ✗ because / although / while:‘除非’用 unless。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp3','choice','{"stem":"\"The things ___ which our forefathers believed have lost their hold.\"(介词+关系代词;‘相信某物’的动词后跟的那个介词)","options":["at","of","in","on"],"answer_index":2,"stem_cn":"我们祖先所信的那些东西,已失去影响力。","explanation_cn":"介词 + 关系代词;‘相信某物’是 believe in,介词用 in。✓ the things in which they believed. ✗ of / at / on:believe 搭配 in。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp3','choice','{"stem":"\"The illness ___ which his friend suffered was unknown to him.\"(介词+关系代词;‘患(病)’的动词后跟的那个介词)","options":["from","of","at","in"],"answer_index":0,"stem_cn":"他并不知道朋友所患的是什么病。","explanation_cn":"介词 + 关系代词;‘患(病)’是 suffer from,介词用 from。✓ the illness from which he suffered. ✗ in / at / of:suffer 搭配 from。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp3','choice','{"stem":"\"The bottle ___ which the pills were kept had no label.\"(介词+关系代词,‘在其中’;‘把…存放在’后跟的那个介词)","options":["from","at","of","in"],"answer_index":3,"stem_cn":"装着药丸的那只瓶子没有标签。","explanation_cn":"介词 + 关系代词;‘把…存放在’是 keep in,介词用 in。✓ the bottle in which the pills were kept. ✗ from / at / of:keep 搭配 in。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp4','choice','{"stem":"\"There is no ___ way of pleasing patients than giving them pills.\"(‘没有比…更快的办法’,填‘快’的比较级形式)","options":["more quick","quick","quicker","quickest"],"answer_index":2,"stem_cn":"没有比给药丸更快讨好病人的办法了。","explanation_cn":"‘没有比…更快的办法’,quick 是单音节形容词,比较级加 -er:quicker。✓ no quicker way than … ✗ quickest(最高级)/ quick(原级)/ more quick:单音节用 -er。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp4','choice','{"stem":"\"A remedy is ___ welcome than time-consuming advice.\"(‘更受欢迎’,welcome 的比较级)","options":["most","much","very","more"],"answer_index":3,"stem_cn":"一剂药方比费时的劝告更受欢迎。","explanation_cn":"welcome 是双音节形容词,比较级前面加 more。✓ more welcome than time-consuming advice. ✗ most(最高级)/ very / much:多音节比较级用 more。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp4','choice','{"stem":"\"Nothing comforts a patient more ___ a bottle to carry home.\"(‘比…更’,比较级后接的那个连词)","options":["then","as","than","that"],"answer_index":2,"stem_cn":"没有什么比一瓶带回家的药更能安慰病人了。","explanation_cn":"比较级后接 than,‘比…’。✓ more … than a bottle to carry home. ✗ then(那时)/ as / that:比较用 than。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp5','choice','{"stem":"\"What patients want is to be ___ quickly.\"(不定式的被动 to be + 过去分词,‘被治好’,填‘治好’那个动词的过去分词)","options":["cured","curing","cures","cure"],"answer_index":0,"stem_cn":"病人想要的是被迅速治好。","explanation_cn":"不定式的被动式 to be + 过去分词,‘被治好’;填‘治好’那个动词的过去分词 cured。✓ to be cured quickly. ✗ curing(主动)/ cure / cures:被动不定式用过去分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp5','choice','{"stem":"\"The medicine is meant to be ___ after meals.\"(不定式的被动 to be + 过去分词,‘被服用’,填‘服用’那个动词的过去分词)","options":["taking","took","taken","take"],"answer_index":2,"stem_cn":"这药应在饭后服用。","explanation_cn":"不定式的被动式 to be + 过去分词,‘被服用’;填‘服用’那个动词的过去分词 taken。✓ meant to be taken after meals. ✗ taking(主动)/ take / took:被动不定式用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp5','choice','{"stem":"\"The advice deserves to be ___ more seriously.\"(不定式的被动 to be + 过去分词,‘被认真对待’,填‘重视/听取’那个动词的过去分词)","options":["to heed","heeded","heeding","heed"],"answer_index":1,"stem_cn":"这忠告值得被更认真地对待。","explanation_cn":"不定式的被动式 to be + 过去分词,‘被认真对待’;填‘重视/听取’那个动词的过去分词 heeded。✓ deserves to be heeded more seriously. ✗ heeding(主动)/ heed / to heed:被动不定式用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp6','choice','{"stem":"\"Something you take or do to cure an illness is a ___.\"(“药物,疗法”用哪个词)","options":["illness","symptom","cause","remedy"],"answer_index":3,"stem_cn":"为治病而服用或采取的东西。","explanation_cn":"为治病而服用或采取的东西是 remedy(药物、疗法)。✓ something to cure an illness is a remedy. ✗ illness 疾病;✗ symptom 症状;✗ cause 病因——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp6','choice','{"stem":"\"Something you can touch or clearly see is ___.\"(“有形的,实实在在的”用哪个词)","options":["sudden","doubtful","tangible","invisible"],"answer_index":2,"stem_cn":"能触摸到或看得清的。","explanation_cn":"能触摸到或看得清的是 tangible(有形的、实实在在的)。✓ something you can touch is tangible. ✗ invisible 看不见的;✗ doubtful 可疑的;✗ sudden 突然的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',5,'am4_l28_gp6','choice','{"stem":"\"When a doctor tells you which medicine to take, he ___ it.\"(“开(药)”用哪个词)","options":["forbids","buys","swallows","prescribes"],"answer_index":3,"stem_cn":"医生告诉你该服什么药,即‘开’药。","explanation_cn":"医生告诉你该服什么药,即‘开(药)’,用 prescribe。✓ the doctor prescribes it. ✗ swallows 吞咽;✗ buys 购买;✗ forbids 禁止——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"skeptical 的意思是:","options":["确定的","轻信的","热情的","怀疑的,多疑的"],"answer_index":3,"explanation_cn":"skeptical = 怀疑的、多疑的。✓ ours is a skeptical age."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"curative 的意思是:","options":["有害的","预防的","有疗效的,治病的","装饰的"],"answer_index":2,"explanation_cn":"curative = 有疗效的、治病的。✓ the curative power of medicine."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"tangible 的意思是:","options":["有形的,实实在在的","无形的","短暂的","虚假的"],"answer_index":0,"explanation_cn":"tangible = 有形的、实实在在的。✓ some tangible remedy."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"remedy 的意思是:","options":["病因","药物,疗法,补救","症状","疾病"],"answer_index":1,"explanation_cn":"remedy = 药物、疗法、补救。✓ a tangible remedy to carry home."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"astronomical 的意思是:","options":["(数字)极大的,天文数字的","微小的","普通的","精确的"],"answer_index":0,"explanation_cn":"astronomical = (数字)极大的、天文数字的。✓ mounting toward astronomical figures."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',6,NULL,'choice','{"stem":"prescribe 的意思是:","options":["购买","开(药),开处方","服用","禁止"],"answer_index":1,"explanation_cn":"prescribe = 开(药)、开处方。✓ a medicine once prescribed."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',7,NULL,'cloze','{"stem":"第 1 空","context":"___1___ our faith in old beliefs has weakened, our trust in medicine has not. Patients feel neglected ___2___ they carry home a bottle. There is no ___3___ way to please them than to give them pills. All they really want is to be ___4___ at no trouble to themselves.","blank_no":1,"options":["Although","Because","Unless","Since"],"answer_index":0,"explanation_cn":"‘尽管…’的让步连词是 Although。✓ Although our faith has weakened, our trust has not."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',7,NULL,'cloze','{"stem":"第 2 空","context":"___1___ our faith in old beliefs has weakened, our trust in medicine has not. Patients feel neglected ___2___ they carry home a bottle. There is no ___3___ way to please them than to give them pills. All they really want is to be ___4___ at no trouble to themselves.","blank_no":2,"options":["unless","because","although","since"],"answer_index":0,"explanation_cn":"‘除非…’的条件连词是 unless。✓ feel neglected unless they carry home a bottle."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',7,NULL,'cloze','{"stem":"第 3 空","context":"___1___ our faith in old beliefs has weakened, our trust in medicine has not. Patients feel neglected ___2___ they carry home a bottle. There is no ___3___ way to please them than to give them pills. All they really want is to be ___4___ at no trouble to themselves.","blank_no":3,"options":["quicker","quickest","quick","more quick"],"answer_index":0,"explanation_cn":"‘没有比…更快的办法’,quick 的比较级 quicker。✓ no quicker way to please them."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',7,NULL,'cloze','{"stem":"第 4 空","context":"___1___ our faith in old beliefs has weakened, our trust in medicine has not. Patients feel neglected ___2___ they carry home a bottle. There is no ___3___ way to please them than to give them pills. All they really want is to be ___4___ at no trouble to themselves.","blank_no":4,"options":["cured","curing","cure","cures"],"answer_index":0,"explanation_cn":"不定式的被动式 to be + 过去分词,‘被治好’。✓ want to be cured at no trouble."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',8,NULL,'choice','{"stem":"What are most patients looking for when they visit the doctor?","options":["A referral to a hospital","Nothing at all","A tangible remedy to carry home, such as a bottle of medicine or pills","A long conversation about their diet"],"answer_index":2,"explanation_cn":"录音说:病人真正想要的,是一样能带回家、看得见摸得着的药——一瓶药水或一盒药片。✓ tangible remedy to carry home."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',8,NULL,'choice','{"stem":"Why do doctors so often give patients what they ask for?","options":["They are overworked and have little time for slow, unwelcome advice","They believe pills always cure illness","Patients refuse to leave","They are paid for each bottle"],"answer_index":0,"explanation_cn":"录音说:医生大多疲于奔命,没工夫慢慢劝人改变生活方式,于是顺手给药了事。✓ overworked, no time for advice."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',8,NULL,'choice','{"stem":"According to the speaker, what do patients really demand of their doctors?","options":["To be told the whole truth","To be given the longest possible treatment","To pay as little as possible","To be cured at no inconvenience to themselves"],"answer_index":3,"explanation_cn":"录音说:病人对医生的真正要求,是毫不费事地把自己治好。✓ cured at no inconvenience."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',9,NULL,'choice','{"stem":"你想说\"尽管我们对旧信仰的信心减弱了,对药物的信任却没有\"(although 让步):","options":["Despite our faith in old beliefs has weakened, our trust in medicine has not.","Although our faith in old beliefs weakened has, our trust in medicine has not.","Although our faith in old beliefs has weakened, our trust in medicine has not.","Although our faith in old beliefs has weakened, but our trust in medicine has not."],"answer_index":2,"explanation_cn":"although 引导让步,‘尽管’;英语里 although 已表转折,句中不能再加 but(不写 …weakened, but…)、也不用 Despite + 从句、语序为 has weakened(不写 weakened has)。✓ Although …, … has not. 场合:说“尽管…,却…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',9,NULL,'choice','{"stem":"你想说\"病人若不带一瓶药回家,就觉得被冷落了\"(unless 条件):","options":["Patients feel neglected unless they carry home a bottle of medicine.","Patients feel neglected unless they will carry home a bottle of medicine.","Patients feel neglected unless they carrying home a bottle of medicine.","Patients feel neglected without they carry home a bottle of medicine."],"answer_index":0,"explanation_cn":"unless 引导‘除非’的条件;从句用一般现在时 carry(不用 will carry、不用 -ing carrying)、且不能用 without + 从句替代。✓ … unless they carry home … 场合:说“除非…否则…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',9,NULL,'choice','{"stem":"你想说\"没有比给药丸更快讨好病人的办法了\"(no + 比较级 … than):","options":["There is no more quick way to please patients than giving them pills.","There is no quicker way to please patients as giving them pills.","There is no quickest way to please patients than giving them pills.","There is no quicker way to please patients than giving them pills."],"answer_index":3,"explanation_cn":"no + 比较级 … than 表‘没有比…更…的’;quick 的比较级 quicker(不用最高级 quickest、不用 more quick)、后接 than(不用 as)。✓ no quicker way … than … 场合:说“没有比…更…的了”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"remedy 的意思是:","options":["疾病","症状","病因","药物,疗法,补救"],"answer_index":3,"explanation_cn":"remedy = 药物、疗法、补救。✓ a tangible remedy to carry home."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"tangible 的意思是:","options":["短暂的","虚假的","有形的,实实在在的","无形的"],"answer_index":2,"explanation_cn":"tangible = 有形的、实实在在的。✓ some tangible remedy."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"\"___ our faith in old beliefs has weakened, our trust in medicine has not.\"(‘尽管’,让步连词)","options":["Since","Because","Unless","Although"],"answer_index":3,"stem_cn":"尽管对旧信仰的信心减弱,对药物的信任却没有。","explanation_cn":"‘尽管’的让步连词是 Although。✓ Although our faith has weakened, our trust has not. ✗ Because / Unless / Since。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"\"Patients feel neglected ___ they carry home a bottle of medicine.\"(‘除非’,条件连词)","options":["unless","because","although","since"],"answer_index":0,"stem_cn":"病人若不带瓶药回家,就觉得被冷落。","explanation_cn":"‘除非’的条件连词是 unless。✓ feel neglected unless they carry home a bottle. ✗ because / although / since。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"\"put up with\" 的意思是:","options":["建立","放弃","举起","忍受,容忍"],"answer_index":3,"explanation_cn":"put up with = 忍受、容忍。✓ put up with the bitter taste."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"\"ask for\" 的意思是:","options":["回答","拒绝","要求,索取","忘记"],"answer_index":2,"explanation_cn":"ask for = 要求、索取。✓ patients ask for pills."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"According to the passage, why do patients feel untreated without a bottle of medicine?","options":["They trust a tangible remedy they can carry home more than advice","The bottle is free","Medicine is the only real cure","Doctors force pills on them"],"answer_index":0,"passage":"Ours is a skeptical age. Although our faith in the things in which our forefathers fervently believed has weakened, our confidence in the curative power of a bottle of medicine remains as strong as ever theirs was. The proof of this modern faith is plain: the yearly drug bill of the health services keeps mounting toward astronomical figures and shows no sign of leveling off. Most patients who attend the clinics of our hospitals feel that they have not been given adequate treatment unless they can carry home some tangible remedy — a bottle of medicine, a box of pills, or a small jar of ointment. Unless the doctor sends them away with something in their hands, they suspect that nothing has been done for them, and the doctor, for his part, is only too ready to oblige. There is no quicker way of dealing with patients than by giving them exactly what they ask for; and since most doctors are overworked and have little time for the slow, thankless business of urging people to eat better and give up their bad habits, the bottle, the box, and the jar are nearly always handed over. It is not only the ignorant who put such faith in the bottle of medicine. There is a story of an old scholar — a learned man in every other respect — who found in his coat pocket what remained of a medicine once prescribed for a slight indisposition of his wife''s. He had no idea what the bottle contained, nor what illness his friend across town was suffering from; but he reasoned that a medicine which had worked so well in one case must surely help in another. Comforted by the thought of the good he was doing, he hurried off to press it upon his friend. The great advantage of taking medicine, after all, is that it asks nothing of the taker beyond putting up for a moment with an unpleasant taste — and that is exactly what patients want of their doctors: to be cured at no inconvenience to themselves.","explanation_cn":"课文说:病人更相信一样能带回家、实实在在的药,而不是费时的劝告,所以没拿到药就觉得没被诊治。✓ trust tangible remedy over advice."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"Why do overworked doctors give patients what they ask for?","options":["Patients pay extra for it","They enjoy prescribing pills","They are told to by the government","It is the quickest way to deal with them, and advice takes time few can spare"],"answer_index":3,"passage":"Ours is a skeptical age. Although our faith in the things in which our forefathers fervently believed has weakened, our confidence in the curative power of a bottle of medicine remains as strong as ever theirs was. The proof of this modern faith is plain: the yearly drug bill of the health services keeps mounting toward astronomical figures and shows no sign of leveling off. Most patients who attend the clinics of our hospitals feel that they have not been given adequate treatment unless they can carry home some tangible remedy — a bottle of medicine, a box of pills, or a small jar of ointment. Unless the doctor sends them away with something in their hands, they suspect that nothing has been done for them, and the doctor, for his part, is only too ready to oblige. There is no quicker way of dealing with patients than by giving them exactly what they ask for; and since most doctors are overworked and have little time for the slow, thankless business of urging people to eat better and give up their bad habits, the bottle, the box, and the jar are nearly always handed over. It is not only the ignorant who put such faith in the bottle of medicine. There is a story of an old scholar — a learned man in every other respect — who found in his coat pocket what remained of a medicine once prescribed for a slight indisposition of his wife''s. He had no idea what the bottle contained, nor what illness his friend across town was suffering from; but he reasoned that a medicine which had worked so well in one case must surely help in another. Comforted by the thought of the good he was doing, he hurried off to press it upon his friend. The great advantage of taking medicine, after all, is that it asks nothing of the taker beyond putting up for a moment with an unpleasant taste — and that is exactly what patients want of their doctors: to be cured at no inconvenience to themselves.","explanation_cn":"课文说:给病人想要的东西是打发他们最快的办法,而劝告耗时,忙碌的医生腾不出时间。✓ quickest way, advice takes time."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"What do patients really want from their doctors, according to the speaker?","options":["To be given the strongest possible drugs","To be cured with no inconvenience to themselves","To spend a long time being examined","To learn about healthy living"],"answer_index":1,"audio":"Ours is a skeptical age. Although our faith in the things in which our forefathers fervently believed has weakened, our confidence in the curative power of a bottle of medicine remains as strong as ever theirs was. The proof of this modern faith is plain: the yearly drug bill of the health services keeps mounting toward astronomical figures and shows no sign of leveling off. Most patients who attend the clinics of our hospitals feel that they have not been given adequate treatment unless they can carry home some tangible remedy — a bottle of medicine, a box of pills, or a small jar of ointment. Unless the doctor sends them away with something in their hands, they suspect that nothing has been done for them, and the doctor, for his part, is only too ready to oblige. There is no quicker way of dealing with patients than by giving them exactly what they ask for; and since most doctors are overworked and have little time for the slow, thankless business of urging people to eat better and give up their bad habits, the bottle, the box, and the jar are nearly always handed over. It is not only the ignorant who put such faith in the bottle of medicine. There is a story of an old scholar — a learned man in every other respect — who found in his coat pocket what remained of a medicine once prescribed for a slight indisposition of his wife''s. He had no idea what the bottle contained, nor what illness his friend across town was suffering from; but he reasoned that a medicine which had worked so well in one case must surely help in another. Comforted by the thought of the good he was doing, he hurried off to press it upon his friend. The great advantage of taking medicine, after all, is that it asks nothing of the taker beyond putting up for a moment with an unpleasant taste — and that is exactly what patients want of their doctors: to be cured at no inconvenience to themselves.","explanation_cn":"课文说:病人对医生的真正要求,是毫不费事地被治好。✓ cured at no inconvenience."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l28',10,NULL,'choice','{"stem":"What is the great advantage of taking medicine, the speaker says?","options":["It replaces the need for doctors","It always works instantly","It asks nothing of you but putting up with a bad taste for a moment","It costs very little"],"answer_index":2,"audio":"Ours is a skeptical age. Although our faith in the things in which our forefathers fervently believed has weakened, our confidence in the curative power of a bottle of medicine remains as strong as ever theirs was. The proof of this modern faith is plain: the yearly drug bill of the health services keeps mounting toward astronomical figures and shows no sign of leveling off. Most patients who attend the clinics of our hospitals feel that they have not been given adequate treatment unless they can carry home some tangible remedy — a bottle of medicine, a box of pills, or a small jar of ointment. Unless the doctor sends them away with something in their hands, they suspect that nothing has been done for them, and the doctor, for his part, is only too ready to oblige. There is no quicker way of dealing with patients than by giving them exactly what they ask for; and since most doctors are overworked and have little time for the slow, thankless business of urging people to eat better and give up their bad habits, the bottle, the box, and the jar are nearly always handed over. It is not only the ignorant who put such faith in the bottle of medicine. There is a story of an old scholar — a learned man in every other respect — who found in his coat pocket what remained of a medicine once prescribed for a slight indisposition of his wife''s. He had no idea what the bottle contained, nor what illness his friend across town was suffering from; but he reasoned that a medicine which had worked so well in one case must surely help in another. Comforted by the thought of the good he was doing, he hurried off to press it upon his friend. The great advantage of taking medicine, after all, is that it asks nothing of the taker beyond putting up for a moment with an unpleasant taste — and that is exactly what patients want of their doctors: to be cured at no inconvenience to themselves.","explanation_cn":"课文说:吃药最大的好处,是它对服药者别无所求,只要忍受片刻难吃的味道。✓ asks nothing but a bad taste."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l29',4,5,29,'The Hovercraft','气垫船','过去完成进行时(had been working for years)、独立主格(the strangest of them being the hovercraft)、情态动词表推测/可能(could span the Atlantic / may well be)、过去分词作定语(ringed with a curtain / ring-shaped)、which 引导定语从句指物(NCE4 无 KS 页,考点由课文结构自取;IP:源为埃贡·拉森《The Pegasus Book of Inventors》‘气垫船’一文,内含真实发明者克里斯托弗·科克雷尔——按 IP 铁律已换成原创虚构工程师;气垫船技术事实(空气垫/兴波阻力/海峡试航)为公开科技史实,用 100% 原创行文复述;题材=交通发明·无害;美语化 tire/aluminum;第四册第29课)','我们这个世纪造出了许多奇特的新型交通工具,其中最奇特的,也许要数气垫船。1953年,一位五十多岁、原是电子工程师、后来在一片静水上改行造船的人,把一个他琢磨了多年的想法,提交给了政府和工业界。那想法就是:用一层低压空气的‘垫’——即气垫——把船托起来,四周再围上一圈高压空气帘。从那以后,人们一直难以断定:该把这机器算作船、算作飞机,还是算作陆上车辆——因为它介于船与飞行器之间。作为造船人,这位发明者一直在跟兴波阻力较劲;兴波阻力会白白耗掉水面船只很大一部分动力,还限制它的速度。他的答案,是靠固定在船底的大量环形气流,把船体整个托离水面。所以它会‘飞’,却飞不高:它的运作,依赖于它所掠过的那层表面——水面或地面。最初的几次试验引起轰动。气垫船先在水上行驶,继而冲上海滩、爬过沙丘,又安安静静地停在一条公路上。后来它横渡英吉利海峡,在浪上平稳滑行,那些浪根本不成问题。从那以后,各式各样的气垫船相继问世,投入了定期营运。这机器在通讯不便的辽阔地区尤其有用,比如非洲或澳大利亚的一些地方;它能把香蕉从种植园运到港口,而巨型气垫班船也许有一天能横渡大西洋。未来的铁路,很可能就是‘气垫火车’——它托在气垫上,在一条它从不接触的单轨上方高速飞驰。种种可能,似乎没有尽头。','{"q":"Listen and answer — What is a hovercraft riding on when it is in motion?","options":["A cushion of low-pressure air, ringed with higher-pressure air","A set of steel rails","A cushion of water","Large rubber wheels"],"answer_index":0}'::jsonb,'{"title":"过去完成进行时 / 独立主格 / 情态推测(could·may well) / 过去分词作定语 / which 定语从句","intro":"①过去完成进行时 had been + 现在分词,表‘在过去某点之前一直在做’:had been working for years。②独立主格 名词 + 现在分词:the strangest of them being the hovercraft。③情态动词表推测/可能:could span the Atlantic;may well be。④过去分词作定语:ringed with a curtain;ring-shaped jets。⑤which 引导定语从句、指物。","table":{"headers":["用法","结构","例子"],"rows":[["过去完成进行时","had been + 现在分词","had been working for years"],["独立主格","名词 + 现在分词","the strangest of them being …"],["情态推测","could / may well + 动词原形","liners could span the Atlantic"],["过去分词作定语","名词 + 过去分词","a pad ringed with a curtain"],["which 定语从句","名词 + which + …","resistance which wastes power"]]},"specialRules":[{"rule":"独立主格里,名词与后面的分词是逻辑上的主谓关系,主动用现在分词(being/roaring)。","mark":"名词 + 现在分词"},{"rule":"may/might well + 动词原形 表‘很可能’;could + 动词原形 表‘也许能/有可能’。","mark":"may well / could"},{"rule":"美式拼写:tire(轮胎,英式 tyre)、aluminum(铝,英式 aluminium)。本课已按美语写。","mark":"tire / aluminum"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l29',1,NULL,'Many strange new means of transport have come out of our century, the strangest of them being perhaps the hovercraft. In 1953 a former electronics engineer in his fifties, a man who had taken up boat-building on a quiet stretch of English water, put before the government and industry an idea he had been turning over for years.','我们这个世纪造出了许多奇特的新型交通工具,其中最奇特的,也许要数气垫船。1953年,一位五十多岁、原是电子工程师、后来在一片静水上改行造船的人,把一个他琢磨了多年的想法,提交给了政府和工业界。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l29',2,NULL,'It was the idea of holding a craft up on a ''pad,'' or cushion, of low-pressure air, ringed with a curtain of higher-pressure air. Ever since, people have found it hard to decide whether the machine should be counted among ships, planes, or land vehicles — for it is something in between a boat and an aircraft.','那想法就是:用一层低压空气的‘垫’——即气垫——把船托起来,四周再围上一圈高压空气帘。从那以后,人们一直难以断定:该把这机器算作船、算作飞机,还是算作陆上车辆——因为它介于船与飞行器之间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l29',3,NULL,'As a shipbuilder, the inventor had been struggling with the problem of wave resistance, which wastes a great deal of a surface ship''s power and limits its speed. His answer was to lift the vessel clear of the water on a great number of ring-shaped air jets fixed to its bottom.','作为造船人,这位发明者一直在跟兴波阻力较劲;兴波阻力会白白耗掉水面船只很大一部分动力,还限制它的速度。他的答案,是靠固定在船底的大量环形气流,把船体整个托离水面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l29',4,NULL,'The craft therefore ''flies,'' but it cannot fly high: its action depends on the surface — water or ground — over which it rides. The first tests caused a sensation. The hovercraft travelled first over the water, then mounted the beach, climbed the dunes, and sat down quietly on a road.','所以它会‘飞’,却飞不高:它的运作,依赖于它所掠过的那层表面——水面或地面。最初的几次试验引起轰动。气垫船先在水上行驶,继而冲上海滩、爬过沙丘,又安安静静地停在一条公路上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l29',5,NULL,'Later it crossed the Channel, riding smoothly over the waves, which presented no problem at all. The machine is especially useful in large regions with poor communications; it can carry bananas from the plantations to the ports, and giant hovercraft liners could one day span the Atlantic. The railway of the future may well be the ''hovertrain,'' riding on its air cushion above a single rail, which it never touches. The possibilities seem unlimited.','后来它横渡英吉利海峡,在浪上平稳滑行,那些浪根本不成问题。这机器在通讯不便的辽阔地区尤其有用;它能把香蕉从种植园运到港口,而巨型气垫班船也许有一天能横渡大西洋。未来的铁路,很可能就是‘气垫火车’——它托在气垫上,在一条它从不接触的单轨上方飞驰。种种可能,似乎没有尽头。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
