INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp1','choice','{"stem":"\"By 1953 the engineer ___ been working on the idea for years.\"(过去完成进行时 __ been + 现在分词,填最前面那个助动词)","options":["had","was","have","has"],"answer_index":0,"stem_cn":"到1953年,那位工程师已在这构想上钻研多年。","explanation_cn":"过去完成进行时 had been + 现在分词;最前面那个助动词是 had。✓ had been working for years. ✗ has / have(时态)/ was:过去完成进行用 had been doing。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp1','choice','{"stem":"\"He suggested an idea on which he ___ been working for a long time.\"(过去完成进行时,填助动词)","options":["have","had","did","has"],"answer_index":1,"stem_cn":"他提出一个自己已研究许久的构想。","explanation_cn":"过去完成进行时 had been + 现在分词。✓ he had been working for a long time. ✗ has / have / did:用 had been doing。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp1','choice','{"stem":"\"Before the first test, the team ___ been building the craft for months.\"(过去完成进行时,填助动词)","options":["have","was","has","had"],"answer_index":3,"stem_cn":"首次试验前,团队已造这船好几个月了。","explanation_cn":"过去完成进行时 had been + 现在分词。✓ the team had been building the craft for months. ✗ has / have / was:用 had been doing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp2','choice','{"stem":"\"Many new machines appeared, the strangest of them ___ the hovercraft.\"(独立主格,名词 + 现在分词,表‘是…’,填‘是’那个词的现在分词)","options":["be","is","being","was"],"answer_index":2,"stem_cn":"许多新机器出现了,其中最奇特的要数气垫船。","explanation_cn":"独立主格:名词 + 现在分词;‘是…’用 be 的现在分词 being。✓ the strangest of them being the hovercraft. ✗ is / was(谓语形式)/ be(原形):独立结构用 being。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp2','choice','{"stem":"\"The craft rose from the water, air jets ___ beneath its hull.\"(独立主格,主动‘轰鸣’,填‘轰鸣’那个动词的现在分词)","options":["roaring","roared","to roar","roar"],"answer_index":0,"stem_cn":"船从水面升起,气流在船体下喷吹轰鸣。","explanation_cn":"独立主格:名词 + 现在分词,主动‘轰鸣’;填‘轰鸣’那个动词的现在分词 roaring。✓ air jets roaring beneath its hull. ✗ roared / roar / to roar:独立结构主动用现在分词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp2','choice','{"stem":"\"The hovercraft crossed the Channel, the waves ___ no problem at all.\"(独立主格,主动‘造成/形成’,填‘造成’那个动词的现在分词)","options":["to present","presenting","present","presented"],"answer_index":1,"stem_cn":"气垫船横渡海峡,海浪根本不成问题。","explanation_cn":"独立主格:名词 + 现在分词,主动‘造成’;填‘造成’那个动词的现在分词 presenting。✓ the waves presenting no problem. ✗ presented / present / to present:独立结构主动用现在分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp3','choice','{"stem":"\"Giant hovercraft liners ___ one day span the Atlantic.\"(情态词表可能,‘也许能’)","options":["could","must","need","should"],"answer_index":0,"stem_cn":"巨型气垫班船也许有一天能横渡大西洋。","explanation_cn":"情态词表可能,‘也许能’;用 could + 动词原形。✓ could one day span the Atlantic. ✗ must(一定)/ should(应该)/ need:表‘也许能’用 could。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp3','choice','{"stem":"\"The railway of the future ___ well be the hovertrain.\"(‘很可能是’,填与 well 连用表推测的情态词)","options":["dare","may","need","would"],"answer_index":1,"stem_cn":"未来的铁路很可能就是气垫火车。","explanation_cn":"‘很可能是’= may/might well + 动词原形;填 may。✓ may well be the hovertrain. ✗ need / dare / would:与 well 连用表推测用 may。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp3','choice','{"stem":"\"A hovercraft ___ carry bananas from the plantations to the ports.\"(情态词表‘能够’)","options":["can","must","shall","ought"],"answer_index":0,"stem_cn":"气垫船能把香蕉从种植园运到港口。","explanation_cn":"情态词表‘能够’,用 can + 动词原形。✓ can carry bananas to the ports. ✗ must / shall / ought:表‘能够’用 can。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp4','choice','{"stem":"\"The craft rides on a pad of air ___ with a curtain of higher pressure.\"(过去分词作定语,被动‘被环绕’,填‘环绕’那个动词的过去分词)","options":["ringing","ring","ringed","to ring"],"answer_index":2,"stem_cn":"船靠一层空气垫托起,四周环着一圈高压气帘。","explanation_cn":"过去分词作定语,被动‘被环绕’;填‘环绕’那个动词的过去分词 ringed。✓ a pad ringed with a curtain. ✗ ringing(主动)/ ring / to ring:被动定语用过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp4','choice','{"stem":"\"A great number of ring-___ air jets lift the vessel.\"(过去分词作定语,‘呈…形状的’,填‘塑形/成形’那个动词的过去分词)","options":["shaping","shape","to shape","shaped"],"answer_index":3,"stem_cn":"大量环形气流把船体托起。","explanation_cn":"过去分词作定语,‘呈…形状的’;填‘塑形/成形’那个动词的过去分词 shaped。✓ ring-shaped air jets. ✗ shaping(主动)/ shape / to shape:此处用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp4','choice','{"stem":"\"The idea, ___ on years of work, was at last accepted.\"(过去分词作定语,被动‘以…为基础’,填‘以…为基础’那个动词的过去分词)","options":["base","to base","based","basing"],"answer_index":2,"stem_cn":"这个基于多年心血的构想终获采纳。","explanation_cn":"过去分词作定语,被动‘以…为基础’;填‘以…为基础’那个动词的过去分词 based。✓ the idea, based on years of work. ✗ basing(主动)/ base / to base:被动定语用过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp5','choice','{"stem":"\"The wave resistance ___ wastes a ship''s power was the real problem.\"(定语从句,指物,在从句里作主语,填关系词)","options":["which","who","whom","whose"],"answer_index":0,"stem_cn":"浪费船只动力的兴波阻力,才是真正的难题。","explanation_cn":"定语从句指物、在从句里作主语,用 which(也可用 that)。✓ the resistance which wastes a ship''s power. ✗ who / whose / whom:指物用 which。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp5','choice','{"stem":"\"The waves, ___ presented no problem, were crossed smoothly.\"(非限定定语从句,指物,填关系词)","options":["whom","which","that","who"],"answer_index":1,"stem_cn":"那些浪根本不成问题,气垫船平稳驶过。","explanation_cn":"前有逗号的非限定定语从句,指物,只能用 which。✓ the waves, which presented no problem. ✗ that / who / whom:非限定指物用 which。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp5','choice','{"stem":"\"The single rail, ___ the hovertrain never touches, guides it along.\"(非限定定语从句,指物,填关系词)","options":["which","whom","who","that"],"answer_index":0,"stem_cn":"那条单轨,气垫火车从不接触,却引着它前行。","explanation_cn":"前有逗号的非限定定语从句,指物,只能用 which。✓ the single rail, which it never touches. ✗ that / who / whom:非限定指物用 which。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp6','choice','{"stem":"\"A soft pad that supports weight, here a layer of air, is a ___.\"(“垫子,气垫”用哪个词)","options":["ladder","mirror","basket","cushion"],"answer_index":3,"stem_cn":"承托重量的软垫,这里指一层空气。","explanation_cn":"承托重量的软垫(这里是一层空气)是 cushion(垫子、气垫)。✓ a soft pad supporting weight is a cushion. ✗ ladder 梯子;✗ mirror 镜子;✗ basket 篮子——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp6','choice','{"stem":"\"A ridge or hill of sand near the sea is a ___.\"(“沙丘”用哪个词)","options":["dune","cave","valley","cliff"],"answer_index":0,"stem_cn":"海边由沙堆成的丘。","explanation_cn":"海边由沙堆成的丘是 dune(沙丘)。✓ a hill of sand near the sea is a dune. ✗ cliff 悬崖;✗ valley 山谷;✗ cave 洞穴——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',5,'am4_l29_gp6','choice','{"stem":"\"A large estate where crops like bananas are grown is a ___.\"(“种植园”用哪个词)","options":["market","factory","harbor","plantation"],"answer_index":3,"stem_cn":"种植香蕉等作物的大庄园。","explanation_cn":"种植香蕉等作物的大庄园是 plantation(种植园)。✓ a large estate for crops is a plantation. ✗ factory 工厂;✗ harbor 港口;✗ market 市场——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"hovercraft 的意思是:","options":["潜艇","帆船","游艇","气垫船"],"answer_index":3,"explanation_cn":"hovercraft = 气垫船。✓ the strangest of them is the hovercraft."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"cushion 的意思是:","options":["垫子,气垫","桅杆","车轮","引擎"],"answer_index":0,"explanation_cn":"cushion = 垫子、气垫。✓ a cushion of low-pressure air."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"sensation 的意思是:","options":["传统","轰动,引起轰动的事","失败","秘密"],"answer_index":1,"explanation_cn":"sensation = 轰动、引起轰动的事。✓ the first tests caused a sensation."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"dune 的意思是:","options":["洞穴","山谷","悬崖","沙丘"],"answer_index":3,"explanation_cn":"dune = 沙丘。✓ climbed the dunes."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"plantation 的意思是:","options":["仓库","种植园","工厂","市场"],"answer_index":1,"explanation_cn":"plantation = 种植园。✓ bananas from the plantations."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',6,NULL,'choice','{"stem":"resistance 的意思是:","options":["引力","速度","阻力,抵抗","动力"],"answer_index":2,"explanation_cn":"resistance = 阻力、抵抗。✓ the problem of wave resistance."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',7,NULL,'cloze','{"stem":"第 1 空","context":"The hovercraft rides on a ___1___ of low-pressure air, ringed with higher pressure. Its inventor ___2___ been working on the idea for years. Giant liners ___3___ one day span the Atlantic. The waves, ___4___ presented no problem, were crossed with ease.","blank_no":1,"options":["cushion","ladder","mirror","basket"],"answer_index":0,"explanation_cn":"承托气垫船的一层空气叫 cushion(气垫)。✓ rides on a cushion of low-pressure air."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',7,NULL,'cloze','{"stem":"第 2 空","context":"The hovercraft rides on a ___1___ of low-pressure air, ringed with higher pressure. Its inventor ___2___ been working on the idea for years. Giant liners ___3___ one day span the Atlantic. The waves, ___4___ presented no problem, were crossed with ease.","blank_no":2,"options":["had","has","have","was"],"answer_index":0,"explanation_cn":"过去完成进行时 had been + 现在分词。✓ the inventor had been working on the idea for years."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',7,NULL,'cloze','{"stem":"第 3 空","context":"The hovercraft rides on a ___1___ of low-pressure air, ringed with higher pressure. Its inventor ___2___ been working on the idea for years. Giant liners ___3___ one day span the Atlantic. The waves, ___4___ presented no problem, were crossed with ease.","blank_no":3,"options":["could","must","should","need"],"answer_index":0,"explanation_cn":"情态词表可能,‘也许能’。✓ liners could one day span the Atlantic."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',7,NULL,'cloze','{"stem":"第 4 空","context":"The hovercraft rides on a ___1___ of low-pressure air, ringed with higher pressure. Its inventor ___2___ been working on the idea for years. Giant liners ___3___ one day span the Atlantic. The waves, ___4___ presented no problem, were crossed with ease.","blank_no":4,"options":["which","that","who","whom"],"answer_index":0,"explanation_cn":"前有逗号的非限定定语从句,指物,用 which。✓ the waves, which presented no problem."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',8,NULL,'choice','{"stem":"What is a hovercraft riding on when it is in motion?","options":["A cushion of low-pressure air, ringed with higher-pressure air","A set of steel rails","Large rubber wheels","A cushion of water"],"answer_index":0,"explanation_cn":"录音说:气垫船靠一层低压空气垫托起,四周由一圈高压空气帘围住。✓ cushion of low-pressure air."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',8,NULL,'choice','{"stem":"What problem was the inventor trying to solve?","options":["The high cost of steel","The noise of engines","The shortage of sailors","The wave resistance that wastes a surface ship''s power and limits its speed"],"answer_index":3,"explanation_cn":"录音说:发明者想解决的是兴波阻力——它白白耗掉水面船只很大动力,还限制其速度。✓ wave resistance."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',8,NULL,'choice','{"stem":"Why can a hovercraft cross both water and land?","options":["It floats on the sea only","It has both wheels and sails","Its action depends only on the surface it rides over, whatever that surface is","It can swim and fly like a bird"],"answer_index":2,"explanation_cn":"录音说:气垫船的运作只取决于它掠过的那层表面(水或地),所以水陆皆可行。✓ depends on the surface."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',9,NULL,'choice','{"stem":"你想说\"到1953年,那位工程师已在这构想上钻研多年\"(过去完成进行时):","options":["By 1953 the engineer had working been on the idea for years.","By 1953 the engineer had been working on the idea for years.","By 1953 the engineer has been working on the idea for years.","By 1953 the engineer had been work on the idea for years."],"answer_index":1,"explanation_cn":"过去完成进行时 had been + 现在分词 working;用 had(不用 has)、been 后接 -ing(不写原形 work)、语序为 had been working(不写 had working been)。✓ had been working … 场合:说“(到过去某点)一直在做…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',9,NULL,'choice','{"stem":"你想说\"许多新机器出现了,其中最奇特的要数气垫船\"(独立主格):","options":["Many new machines appeared, the strangest of them being the hovercraft.","Many new machines appeared, the strangest of them been the hovercraft.","Many new machines appeared, the strangest of them is the hovercraft.","Many new machines appeared, the strangest of them be the hovercraft."],"answer_index":0,"explanation_cn":"独立结构:名词 the strangest of them + 现在分词 being;表‘是…’用 being(不用原形 be、过去分词 been,也不用作句子动词的 is)。✓ …, the strangest of them being … 场合:补充说明‘其中…是…’。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',9,NULL,'choice','{"stem":"你想说\"巨型气垫班船也许有一天能横渡大西洋\"(情态词表推测):","options":["Giant hovercraft liners could to one day span the Atlantic.","Giant hovercraft liners could one day spans the Atlantic.","Giant hovercraft liners could one day span the Atlantic.","Giant hovercraft liners can could one day span the Atlantic."],"answer_index":2,"explanation_cn":"情态词 could + 动词原形 span 表‘也许能’;span 用原形(不加 s、不加 to)、且不与 can 叠用(不写 can could)。✓ could … span … 场合:说“也许有一天能…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"hovercraft 的意思是:","options":["气垫船","游艇","潜艇","帆船"],"answer_index":0,"explanation_cn":"hovercraft = 气垫船。✓ the strangest of them is the hovercraft."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"dune 的意思是:","options":["山谷","洞穴","沙丘","悬崖"],"answer_index":2,"explanation_cn":"dune = 沙丘。✓ climbed the dunes."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"\"By 1953 the engineer ___ been working on the idea for years.\"(过去完成进行时,填最前面那个助动词)","options":["was","had","have","has"],"answer_index":1,"stem_cn":"到1953年,那位工程师已钻研多年。","explanation_cn":"过去完成进行时 had been + 现在分词。✓ had been working on the idea for years. ✗ has / have / was。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"\"Many new machines appeared, the strangest of them ___ the hovercraft.\"(独立主格,填‘是’那个词的现在分词)","options":["being","is","be","was"],"answer_index":0,"stem_cn":"许多新机器出现,最奇特的要数气垫船。","explanation_cn":"独立结构:名词 + 现在分词,‘是…’用 being。✓ the strangest of them being the hovercraft. ✗ is / was / be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"\"depend on\" 的意思是:","options":["离开","依赖,取决于","拒绝","忽视"],"answer_index":1,"explanation_cn":"depend on = 依赖、取决于。✓ the hovercraft depends on the surface below."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"\"ever since\" 的意思是:","options":["在那之前","偶尔","从那以后一直","从不"],"answer_index":2,"explanation_cn":"ever since = 从那以后一直。✓ ever since, people have argued about it."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"How does a hovercraft support itself?","options":["On a cushion of low-pressure air held in by a curtain of higher-pressure air","On a bed of steel springs","On floating logs","On a magnetic field"],"answer_index":0,"passage":"Many strange new means of transport have come out of our century, the strangest of them being perhaps the hovercraft. In 1953 a former electronics engineer in his fifties, a man who had taken up boat-building on a quiet stretch of English water, put before the government and industry an idea he had been turning over for years. It was the idea of holding a craft up on a ''pad,'' or cushion, of low-pressure air, ringed with a curtain of higher-pressure air. Ever since, people have found it hard to decide whether the machine should be counted among ships, planes, or land vehicles — for it is something in between a boat and an aircraft. As a shipbuilder, the inventor had been struggling with the problem of wave resistance, which wastes a great deal of a surface ship''s power and limits its speed. His answer was to lift the vessel clear of the water on a great number of ring-shaped air jets fixed to its bottom. The craft therefore ''flies,'' but it cannot fly high: its action depends on the surface — water or ground — over which it rides. The first tests caused a sensation. The hovercraft travelled first over the water, then mounted the beach, climbed the dunes, and sat down quietly on a road. Later it crossed the Channel, riding smoothly over the waves, which presented no problem at all. Since then, various kinds of hovercraft have appeared and taken up regular service. The machine is especially useful in large regions with poor communications, such as parts of Africa or Australia; it can carry bananas from the plantations to the ports, and giant hovercraft liners could one day span the Atlantic. The railway of the future may well be the ''hovertrain,'' riding on its air cushion above a single rail, which it never touches, at great speed. The possibilities seem unlimited.","explanation_cn":"课文说:气垫船靠一层低压空气垫托起,四周被一圈高压空气帘围住。✓ cushion held by curtain."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"Why is the hovercraft hard to classify as ship, plane, or land vehicle?","options":["It is faster than all of them","It is something in between a boat and an aircraft","It has no engine","It cannot move at all"],"answer_index":1,"passage":"Many strange new means of transport have come out of our century, the strangest of them being perhaps the hovercraft. In 1953 a former electronics engineer in his fifties, a man who had taken up boat-building on a quiet stretch of English water, put before the government and industry an idea he had been turning over for years. It was the idea of holding a craft up on a ''pad,'' or cushion, of low-pressure air, ringed with a curtain of higher-pressure air. Ever since, people have found it hard to decide whether the machine should be counted among ships, planes, or land vehicles — for it is something in between a boat and an aircraft. As a shipbuilder, the inventor had been struggling with the problem of wave resistance, which wastes a great deal of a surface ship''s power and limits its speed. His answer was to lift the vessel clear of the water on a great number of ring-shaped air jets fixed to its bottom. The craft therefore ''flies,'' but it cannot fly high: its action depends on the surface — water or ground — over which it rides. The first tests caused a sensation. The hovercraft travelled first over the water, then mounted the beach, climbed the dunes, and sat down quietly on a road. Later it crossed the Channel, riding smoothly over the waves, which presented no problem at all. Since then, various kinds of hovercraft have appeared and taken up regular service. The machine is especially useful in large regions with poor communications, such as parts of Africa or Australia; it can carry bananas from the plantations to the ports, and giant hovercraft liners could one day span the Atlantic. The railway of the future may well be the ''hovertrain,'' riding on its air cushion above a single rail, which it never touches, at great speed. The possibilities seem unlimited.","explanation_cn":"课文说:气垫船既像船又像飞机,介于两者之间,所以难以归类。✓ in between boat and aircraft."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"What did the first tests lead the hovercraft to do?","options":["Sink beneath the waves","Fly high into the air","Travel over water, then mount the beach and cross land","Stay in the harbor"],"answer_index":2,"audio":"Many strange new means of transport have come out of our century, the strangest of them being perhaps the hovercraft. In 1953 a former electronics engineer in his fifties, a man who had taken up boat-building on a quiet stretch of English water, put before the government and industry an idea he had been turning over for years. It was the idea of holding a craft up on a ''pad,'' or cushion, of low-pressure air, ringed with a curtain of higher-pressure air. Ever since, people have found it hard to decide whether the machine should be counted among ships, planes, or land vehicles — for it is something in between a boat and an aircraft. As a shipbuilder, the inventor had been struggling with the problem of wave resistance, which wastes a great deal of a surface ship''s power and limits its speed. His answer was to lift the vessel clear of the water on a great number of ring-shaped air jets fixed to its bottom. The craft therefore ''flies,'' but it cannot fly high: its action depends on the surface — water or ground — over which it rides. The first tests caused a sensation. The hovercraft travelled first over the water, then mounted the beach, climbed the dunes, and sat down quietly on a road. Later it crossed the Channel, riding smoothly over the waves, which presented no problem at all. Since then, various kinds of hovercraft have appeared and taken up regular service. The machine is especially useful in large regions with poor communications, such as parts of Africa or Australia; it can carry bananas from the plantations to the ports, and giant hovercraft liners could one day span the Atlantic. The railway of the future may well be the ''hovertrain,'' riding on its air cushion above a single rail, which it never touches, at great speed. The possibilities seem unlimited.","explanation_cn":"课文说:首次试验中,气垫船先在水上行驶,又冲上海滩、爬过沙丘、停在公路上。✓ over water then onto land."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l29',10,NULL,'choice','{"stem":"Where is the hovercraft especially useful?","options":["Only in deserts","In large areas with poor communications, such as parts of Africa or Australia","Only in crowded cities","Only on railways"],"answer_index":1,"audio":"Many strange new means of transport have come out of our century, the strangest of them being perhaps the hovercraft. In 1953 a former electronics engineer in his fifties, a man who had taken up boat-building on a quiet stretch of English water, put before the government and industry an idea he had been turning over for years. It was the idea of holding a craft up on a ''pad,'' or cushion, of low-pressure air, ringed with a curtain of higher-pressure air. Ever since, people have found it hard to decide whether the machine should be counted among ships, planes, or land vehicles — for it is something in between a boat and an aircraft. As a shipbuilder, the inventor had been struggling with the problem of wave resistance, which wastes a great deal of a surface ship''s power and limits its speed. His answer was to lift the vessel clear of the water on a great number of ring-shaped air jets fixed to its bottom. The craft therefore ''flies,'' but it cannot fly high: its action depends on the surface — water or ground — over which it rides. The first tests caused a sensation. The hovercraft travelled first over the water, then mounted the beach, climbed the dunes, and sat down quietly on a road. Later it crossed the Channel, riding smoothly over the waves, which presented no problem at all. Since then, various kinds of hovercraft have appeared and taken up regular service. The machine is especially useful in large regions with poor communications, such as parts of Africa or Australia; it can carry bananas from the plantations to the ports, and giant hovercraft liners could one day span the Atlantic. The railway of the future may well be the ''hovertrain,'' riding on its air cushion above a single rail, which it never touches, at great speed. The possibilities seem unlimited.","explanation_cn":"课文说:气垫船在通讯不便的辽阔地区尤其有用,如非洲或澳大利亚的部分地方。✓ large areas, poor communications."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
